                if dest_path.is_symlink() {
                    fs::remove_file(&dest_path).map_err(|e| {
                        io::Error::new(
                            e.kind(),
                            format!("removing destination alias {}: {e}", dest_path.display()),
                        )
                    })?;
                }
                // Never copy a file onto itself (an $ORIGIN search dir that
