+                if let Ok(entries) = fs::read_dir(&gs_dir) {
+                    for entry in entries.filter_map(Result::ok) {
+                        let schemas = entry.path().join("glib-2.0/schemas");
+                        if schemas.is_dir() && !schema_dirs.contains(&schemas) {
+                            schema_dirs.push(schemas);
