+    let mut xml_count = 0usize;
+    let mut seen: HashSet<String> = HashSet::new();
+    for schema_dir in &schema_dirs {
+        let Ok(entries) = fs::read_dir(schema_dir) else {
+            continue;
+        };
+        for entry in entries.filter_map(Result::ok) {
